+/** Theoretical and actual consumption by item for inclusive UTC days. */
+export function varianceReport(store, from, to) {
+  const totals = new Map();
+  const add = (itemId, field, qty) => {
+    const entry = totals.get(itemId) ?? { itemId, theoretical: 0, actual: 0 };
+    entry[field] = Math.round((entry[field] + qty) * 1000) / 1000;
+    totals.set(itemId, entry);
+  };
+  for (const sale of store.data.sales) {
+    const day = sale.soldAt.slice(0, 10);
+    if (day >= from && day <= to) for (const i of sale.ingredients) add(i.itemId, "theoretical", i.qty);
+  }
+  for (const m of store.data.movements) {
+    if (m.type !== "consume" || m.qty <= 0) continue;
+    const day = new Date(m.at).toISOString().slice(0, 10);
+    if (day < from || day > to) continue;
+    const batch = store.data.batches.find((b) => b.id === m.batchId);
+    if (batch) add(batch.itemId, "actual", m.qty);
+  }
+  return [...totals.values()].filter((v) => v.theoretical > 0 || v.actual > 0)
+    .map((v) => ({ ...v, difference: Math.round((v.actual - v.theoretical) * 1000) / 1000 }))
+    .sort((a, b) => a.itemId - b.itemId);
+}
